def transform(grid, center_offset=None):
    from collections import Counter
    c=Counter(v for r in grid for v in r)
    bg=c.most_common(1)[0][0]
    h,w=len(grid),len(grid[0])
    rest=[v for v in c if v!=bg]
    # markers = most frequent of rest, shape = others
    counts={v:c[v] for v in rest}
    marker=max(counts,key=lambda v:counts[v])
    shape=[(i,j) for i in range(h) for j in range(w) if grid[i][j] not in (bg,marker)]
    rs={i for i,j in shape}; cs={j for i,j in shape}
    top,left=min(rs),min(cs)
    sh=[[grid[i][j] for j in range(left,max(cs)+1)] for i in range(top,max(rs)+1)]
    hh,ww=len(sh),len(sh[0])
    # find which cell of shape overlaps the marker cluster in input? marker is separate; assume center
    # center offset: which (di,dj) of shape lands on marker
    di,dj=(hh-1)//2,(ww-1)//2
    out=[row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==marker:
                for a in range(hh):
                    for b in range(ww):
                        v=sh[a][b]
                        if v!=marker:
                            ni,nj=i+a-di,j+b-dj
                            if 0<=ni<h and 0<=nj<w: out[ni][nj]=v
    return out
